/// <summary>
/// Service class for transfer picking list generation service
/// </summary>
class METTransferPickingListAutoGenerationService extends SysOperationServiceBase
{
    METTransferPickingListAutoGenerationContract    dataContract;
    BatchHeader                                     batchHeader;



}

Method.Source:
/// <summary>
/// processing logic
/// </summary>
/// <param name = "_dataContract">The data contract</param>
public void process(METTransferPickingListAutoGenerationContract _dataContract)
{
    dataContract = _dataContract;

    this.initialise();
    this.processTasks();
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    if (this.isExecutingInBatch())
    {
        batchHeader = this.getCurrentBatchHeader();
    }
    else
    {
        batchHeader = BatchHeader::construct();
        batchHeader.parmCaption("@MET:AutoExtractTO");
    }
}

/// <summary>Create sub tasks that do the actual calculations</summary>
public void processTasks()
{
    int i;
    METTransferPickingListGenerationTaskController      transferPickingListGenerationTaskController, transferPickingListGenerationTaskControllerFinal;
    METTransferPickingListGenerationTaskContract        transferPickingListGenerationTaskContract;
    MetShipmentId       metShipmentId;
    container           conShipmentIds;
    InventTransferTable transferTable;
    List                transferPickingListGenerationTaskControllerList;
    ListEnumerator      enumerator;

    boolean             isShipmentRequired = dataContract.parmIsFinalisationRequired();
    Query               transferOrderQuery = dataContract.getQuery();
    QueryRun            transferOrderQueryRun = new QueryRun(transferOrderQuery);
    int recordCount;
    int loopCount;

    recordCount = SysQuery::countLoops(transferOrderQueryRun);
    transferPickingListGenerationTaskControllerList = new List(Types::Class);

    while (transferOrderQueryRun.next())
    {
        loopCount++;

        transferTable = transferOrderQueryRun.get(tableNum(InventTransferTable));

        transferPickingListGenerationTaskController = METTransferPickingListGenerationTaskController::construct();
        transferPickingListGenerationTaskContract   = this.buildDataContract(transferPickingListGenerationTaskController, transferTable.TransferId);

        //transferPickingListGenerationTaskController.startOperation();

        if (isShipmentRequired)
        {
            //Create shipment header and loads to prevent the batch task dead lock issue.
            METOrderShipmentLoadCreation        metOrderShipmentloadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::TransferOrder,
                                                                                                                    transferTable.TransferId);
            metShipmentId = metOrderShipmentloadCreation.createShippmentLoad(true, true);

            if (conFind(conShipmentIds, metShipmentId) == 0)
            {
                conShipmentIds += [metShipmentId];
            }
        }

        transferPickingListGenerationTaskContract.parmSkipFinalisationProcess(!isShipmentRequired);

        if (recordCount == loopCount)
        {
            transferPickingListGenerationTaskContract.parmShipmentIdList(conShipmentIds);
            transferPickingListGenerationTaskContract.parmTriggerBusinessEvent(true);

            transferPickingListGenerationTaskControllerFinal = transferPickingListGenerationTaskController;
        }
        else
        {
            // Add to list for dependency tracking
            transferPickingListGenerationTaskControllerList.addEnd(transferPickingListGenerationTaskController);
        }

        if (this.isExecutingInBatch())
        {
            batchHeader.addRuntimeTask(transferPickingListGenerationTaskController, this.getCurrentBatchTask().RecId);
        }
        else
        {
            batchHeader.addTask(transferPickingListGenerationTaskController);
        }
    }

    // Add dependency so that finalisation task runs at the end
    enumerator = transferPickingListGenerationTaskControllerList.getEnumerator();
    while (enumerator.moveNext())
    {
        transferPickingListGenerationTaskController =  enumerator.current();
        batchHeader.addDependency(transferPickingListGenerationTaskControllerFinal, transferPickingListGenerationTaskController);
    }

    batchHeader.save();
}

/// <summary>
/// contract METTransferPickingListGenerationTaskContract
/// </summary>
/// <param name = "_taskController">METTransferPickingListGenerationTaskController</param>
/// <param name = "_transferOrderId">transfer order list</param>
/// <returns>METTransferPickingListGenerationTaskContract</returns>
public METTransferPickingListGenerationTaskContract buildDataContract(METTransferPickingListGenerationTaskController _taskController, InventTransferId _transferOrderId)
{
    METTransferPickingListGenerationTaskContract   transferPickingListGenerationTaskContract;

    transferPickingListGenerationTaskContract = _taskController.getDataContractObject();
    transferPickingListGenerationTaskContract.parmTransferId(_transferOrderId);

    // Task 424597: pass picking list parameters from the batch job to each runtime task.
    // Only this job sets the override, so the extraction screen and cross dock paths keep legacy behaviour.
    transferPickingListGenerationTaskContract.parmOverridePickingListParms(true);
    transferPickingListGenerationTaskContract.parmReservation(dataContract.parmReservation());
    transferPickingListGenerationTaskContract.parmPickUpdateQty(dataContract.parmPickUpdateQty());

    return transferPickingListGenerationTaskContract;
}
